/**
 * جدول الشوارع والأزقة (المرحلة ④) — عرض جدولي كامل مع فلاتر وتصدير CSV.
 *
 * لماذا جدول مستقل عن المحرّر: المحرّر للتصحيح البصري على الخريطة؛ الجدول
 * للمراجعة السريعة والفرز والتصدير. المشرف يحتاجهما معاً لا أحدهما.
 */
import { useMemo, useState } from 'react'
import { Download, FileSpreadsheet } from 'lucide-react'
import { ExecPageHeader } from '@components/executive/ExecPageHeader'
import { useNavigate } from 'react-router'
import {
  KIND_LABEL_AR,
  STATUS_LABEL_AR,
  type MapAlley,
  type MapPoint,
  type MapStreet,
  type StreetKind,
} from '@sdk/map-planning.sdk'
import {
  useCoverageByPlace,
  useExportPrefs,
  useMapAlleys,
  useMapMahallas,
  useMapStreets,
  useMapZones,
  useSectorManagers,
} from '@features/map-planning/hooks/useMapPlanning'
import { buildExcelReport, saveWorkbook } from '@lib/export/excel-report'
import { ExportColumnsPanel } from '@features/map-planning/components/ExportColumnsPanel'
import { MapFilterBar } from '@features/map-planning/components/MapFilterBar'
import { useUrlBool, useUrlChoice, useUrlState, useUrlText } from '@features/map-planning/hooks/useUrlState'
import {
  defaultSelection,
  resolveColumns,
  toReportColumns,
  toReportRows,
  totalRow,
  type ColumnContext,
  type ColumnSelection,
  type Row as ExportRow,
} from '@features/map-planning/export-columns'
import { mapPlanningSdk } from '@sdk/map-planning.sdk'
import { useShiftLabel } from '@features/hr-shifts/hooks'

/**
 * صفّ الجدول يحمل **معرّف العنصر ومساره الهندسي** لا حقول العرض فقط.
 *
 * لماذا: الضغط على الصف يجب أن ينقل المستخدم إلى موضعه على الخريطة. بلا `id`
 * و`path` لا يعرف الصف أين يقع، فيبقى الجدول معزولاً عن الخريطة. `path` موجود
 * أصلاً في `MapStreet`/`MapAlley` من نفس استعلام `useMapStreets/useMapAlleys`
 * — لا استعلام إضافي ولا تكلفة شبكة.
 */
type Row = {
  /** معرّف الصفّ في `map_streets` أو `map_alleys` — مفتاح الرابط إلى الخريطة */
  id: string
  kind: 'street' | 'alley'
  code: string
  name: string | null
  cls: string
  length_m: number
  width_m: number | null
  mahalla: string
  status: string
  /** مسار العنصر `[lat, lng]` — يُستخدم لتركيز الخريطة على موضعه */
  path: MapPoint[]
}

type SortKey = 'code' | 'length_m' | 'width_m' | 'name'
type Tab = 'all' | 'streets' | 'alleys' | 'unassigned'

/** يوم بغداد (UTC+3) — لا يوم UTC */
const todayBaghdad = () => new Date(Date.now() + 3 * 60 * 60_000).toISOString().slice(0, 10)

export default function MapPlanningTablePage() {
  const { data: zones = [] } = useMapZones()
  // المرشّحات في العنوان — رابط «كل أزقة الكراج بلا محلة» صار قابلاً للإرسال
  const [zoneParam, setZoneId] = useUrlState<string | null>('zone', {
    fallback: null,
    parse: (raw) => raw || undefined,
    serialize: (v) => v ?? '',
  })
  const activeZoneId = zoneParam ?? zones[0]?.id ?? null
  const { data: streets = [], isLoading: ls } = useMapStreets(activeZoneId)
  const { data: alleys = [], isLoading: la } = useMapAlleys(activeZoneId)
  const { data: mahallas = [] } = useMapMahallas(activeZoneId)
  const activeZone = zones.find((z) => z.id === activeZoneId)
  /** الشفت من `hr_shifts` حيّاً — لا قائمة ثابتة بثلاثة رموز */
  const shiftLabel = useShiftLabel()
  /** مسؤولو القاطع — يُستنتجون من القاطع، ويُطبَّقون على كل صفوف التقرير */
  const { data: sectorMgrs = [] } = useSectorManagers(
    activeZone?.sector_id ? [activeZone.sector_id] : [],
  )
  const managersForZone =
    sectorMgrs.find((m) => m.sector_id === activeZone?.sector_id)?.manager_names ?? null

  const [tab, setTab] = useUrlChoice<Tab>('tab', ['all', 'streets', 'alleys', 'unassigned'], 'all')
  const [query, setQuery] = useUrlText('q')
  const [kinds, setKinds] = useState<Set<StreetKind>>(
    new Set(['primary', 'secondary', 'tertiary', 'local']),
  )
  const [minLen, setMinLen] = useState('')
  const [noWidth, setNoWidth] = useUrlBool('noWidth')
  const [sortKey, setSortKey] = useState<SortKey>('code')
  const [asc, setAsc] = useState(true)
  const [showColumns, setShowColumns] = useState(false)
  const [saving, setSaving] = useState(false)

  // أعمدة التقرير: تفضيل المستخدم المحفوظ، وإلا الافتراضي المعلن
  const day = todayBaghdad()
  const { data: prefs } = useExportPrefs('places')
  const [override, setOverride] = useState<ColumnSelection[] | null>(null)
  const selection: ColumnSelection[] =
    override ?? (prefs && prefs.length > 0 ? prefs : defaultSelection('places'))
  // بيانات التغطية تُثري التصدير بحالة كل مكان في يوم بغداد
  const { data: coverage = [] } = useCoverageByPlace(activeZoneId, day)

  const rows: Row[] = useMemo(() => {
    const out: Row[] = []
    if (tab !== 'alleys') {
      for (const s of streets as MapStreet[]) {
        if (s.status === 'archived' || !kinds.has(s.kind)) continue
        out.push({
          id: s.id,
          kind: 'street',
          code: s.code,
          name: s.name,
          cls: KIND_LABEL_AR[s.kind],
          length_m: s.length_m,
          width_m: s.width_m,
          mahalla: '—',
          status: STATUS_LABEL_AR[s.status],
          path: s.path ?? [],
        })
      }
    }
    if (tab !== 'streets') {
      for (const a of alleys as MapAlley[]) {
        if (a.status === 'archived') continue
        if (tab === 'unassigned' && a.mahalla_code !== 'MHL-0000') continue
        out.push({
          id: a.id,
          kind: 'alley',
          code: a.code,
          name: a.name,
          cls: 'زقاق',
          length_m: a.length_m,
          width_m: a.width_m,
          mahalla: a.mahalla_name ?? 'بلا محلة',
          status: STATUS_LABEL_AR[a.status],
          path: a.path ?? [],
        })
      }
    }
    const q = query.trim().toLowerCase()
    const minV = Number(minLen) || 0
    const filtered = out.filter(
      (r) =>
        (!q || r.code.toLowerCase().includes(q) || (r.name ?? '').toLowerCase().includes(q)) &&
        r.length_m >= minV &&
        (!noWidth || r.width_m === null),
    )
    filtered.sort((a, b) => {
      let c = 0
      if (sortKey === 'length_m') c = a.length_m - b.length_m
      else if (sortKey === 'width_m') c = (a.width_m ?? -1) - (b.width_m ?? -1)
      else if (sortKey === 'name') c = (a.name ?? '').localeCompare(b.name ?? '', 'ar')
      else c = a.code.localeCompare(b.code, 'ar')
      return asc ? c : -c
    })
    return filtered
  }, [streets, alleys, tab, kinds, query, minLen, noWidth, sortKey, asc])

  const toggleKind = (k: StreetKind) =>
    setKinds((prev) => {
      const n = new Set(prev)
      if (n.has(k)) n.delete(k)
      else n.add(k)
      return n
    })

  const sortBy = (k: SortKey) => {
    if (k === sortKey) setAsc((v) => !v)
    else {
      setSortKey(k)
      setAsc(true)
    }
  }

  const ctx: ColumnContext = {
    zoneName: zones.find((z) => z.id === activeZoneId)?.name ?? '—',
    shiftLabel,
  }

  /** صفوف التصدير = **نفس** المفلتر المعروض على الشاشة (معيار قبول الخطة) */
  const exportRows: ExportRow[] = useMemo(() => {
    const covByPlace = new Map(
      (
        coverage as {
          place_kind: string
          place_code: string
          visited: boolean
          confirmed: boolean
          visits_count: number
          vehicles_count: number
          total_dwell_seconds: number
          first_entered_at: string | null
          last_exited_at: string | null
        }[]
      ).map((c) => [`${c.place_kind}:${c.place_code}`, c]),
    )
    return rows.map((r) => {
      const kind: 'street' | 'alley' = r.kind === 'street' ? 'street' : 'alley'
      const c = covByPlace.get(`${kind}:${r.code}`)
      return {
        place_kind: kind,
        place_code: r.code,
        place_name: r.name,
        mahalla_code: r.mahalla === 'بلا محلة' || r.mahalla === '—' ? null : r.mahalla,
        length_m: r.length_m,
        width_m: r.width_m,
        status_ar: r.status,
        visited: c?.visited ?? false,
        confirmed: c?.confirmed ?? false,
        visits_count: c?.visits_count ?? 0,
        vehicles_count: c?.vehicles_count ?? 0,
        total_dwell_seconds: c?.total_dwell_seconds ?? 0,
        first_entered_at: c?.first_entered_at ?? null,
        last_exited_at: c?.last_exited_at ?? null,
        department_manager_names: managersForZone,
      } satisfies ExportRow
    })
  }, [rows, coverage, managersForZone])

  const exportExcel = async () => {
    if (!activeZoneId) return
    setSaving(true)
    try {
      const cols = resolveColumns('places', selection)
      const zoneName = ctx.zoneName
      const wb = await buildExcelReport({
        sheetName: 'التخطيط والتغطية',
        companySub: 'غرفة العمليات — التخطيط الجغرافي',
        title: `تقرير الشوارع والأزقة — ${zoneName}`,
        meta:
          `يوم ${day} (بغداد) · ${exportRows.length} صفاً · ${cols.length} عموداً · ` +
          `${exportRows.filter((r) => r.confirmed).length} مؤكد · ` +
          `${exportRows.filter((r) => r.visited && !r.confirmed).length} غير مؤكد · ` +
          `${exportRows.filter((r) => !r.visited).length} لم تُدخل`,
        columns: toReportColumns(cols),
        rows: toReportRows(exportRows, cols, ctx),
        totalRow: totalRow(exportRows, cols, ctx),
        orientation: 'landscape',
        fileName: `map-${zones.find((z) => z.id === activeZoneId)?.code ?? 'zone'}-${day}.xlsx`,
        deferSave: true,
      })
      await saveWorkbook(
        wb,
        `map-${zones.find((z) => z.id === activeZoneId)?.code ?? 'zone'}-${day}.xlsx`,
      )
      // أثر التصدير — لا يُعطّل التنزيل إن فشل تسجيله
      void mapPlanningSdk
        .exportLogAdd({
          zoneId: activeZoneId,
          kind: 'places',
          from: day,
          to: day,
          rowCount: exportRows.length,
          columns: selection,
        })
        .catch(() => undefined)
    } finally {
      setSaving(false)
    }
  }

  const loading = ls || la
  const missingWidth = rows.filter((r) => r.width_m === null).length

  /**
   * «أين يقع هذا الصفّ؟» — الضغط على الصف ينقل إلى محرّر الخريطة على **الزون
   * نفسه** مع تمرير العنصر في `focus`، فيُختار ويُبرَز ويُلامَس موضعه.
   *
   * لماذا المحرّر لا نافذة منبثقة: هو الخريطة الوحيدة التي ترسم الشوارع
   * والأزقة فعلاً، وتفتح بطاقة تفاصيل العنصر وإمكانية تصحيحه. نافذة ثانية
   * ستكرّر الشيفرة وتفصل «أرى» عن «أصحّح».
   */
  const navigate = useNavigate()
  const openOnMap = (row: Row) => {
    if (!activeZoneId) return
    navigate(
      `/ops-room/map-planning?zone=${encodeURIComponent(activeZoneId)}&focus=${row.kind}:${row.id}`,
    )
  }

  return (
    <div className="space-y-4" dir="rtl">
      <ExecPageHeader
        icon="file-spreadsheet"

        title="جدول الشوارع والأزقة"
        subtitle={`${rows.length} صفاً · ${missingWidth} بلا عرض مقيس · اضغط أي صف لعرض موضعه على الخريطة`}
        actions={
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setShowColumns((v) => !v)}
              aria-pressed={showColumns}
              className="flex items-center gap-1 rounded-xl bg-white/10 px-3 py-2 text-xs font-black text-white ring-1 ring-white/20"
            >
              <FileSpreadsheet size={14} /> الأعمدة ({resolveColumns('places', selection).length})
            </button>
            <button
              type="button"
              onClick={() => void exportExcel()}
              disabled={saving || !activeZoneId}
              className="flex items-center gap-1 rounded-xl bg-white/15 px-3 py-2 text-xs font-black text-white ring-1 ring-white/25 disabled:opacity-50"
            >
              <Download size={14} /> {saving ? 'يُصدّر…' : 'تصدير Excel'}
            </button>
          </div>
        }
        links={[
          { to: '/ops-room/map-planning/visits', label: 'الزيارات والتغطية', icon: 'activity' },
        ]}
      />

      <MapFilterBar
        zones={zones.map((z) => ({
          id: z.id,
          name: z.name,
          count: z.id === activeZoneId ? rows.length : undefined,
        }))}
        activeZoneId={activeZoneId}
        onPickZone={setZoneId}
        query={query}
        onQueryChange={setQuery}
        queryPlaceholder="كود أو اسم"
        shown={rows.length}
        total={streets.length + alleys.length}
        unitLabel="صفّ"
        dirty={
          zoneParam !== null || tab !== 'all' || query !== '' || noWidth || minLen !== '' ||
          kinds.size !== 4
        }
        onClearAll={() => {
          setZoneId(null)
          setTab('all')
          setQuery('')
          setNoWidth(false)
          setMinLen('')
          setKinds(new Set(['primary', 'secondary', 'tertiary', 'local']))
        }}
        extra={
          <>
            {(['all', 'streets', 'alleys', 'unassigned'] as Tab[]).map((t) => (
          <button
            key={t}
            type="button"
            onClick={() => setTab(t)}
            aria-pressed={tab === t}
            className={`rounded-xl px-3 py-2 text-[11px] font-black ${tab === t ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-700'}`}
          >
            {t === 'all'
              ? 'الكل'
              : t === 'streets'
                ? 'شوارع'
                : t === 'alleys'
                  ? 'أزقة'
                  : 'بلا محلة'}
              </button>
            ))}
            <span className="mx-1 h-5 w-px bg-slate-200" />
            {(['primary', 'secondary', 'tertiary', 'local'] as StreetKind[]).map((k) => (
              <button
                key={k}
                type="button"
                onClick={() => toggleKind(k)}
                aria-pressed={kinds.has(k)}
                className={`rounded-xl px-2.5 py-2 text-[11px] font-black ${kinds.has(k) ? 'bg-slate-800 text-white' : 'bg-slate-100 text-slate-400'}`}
              >
                {KIND_LABEL_AR[k]}
              </button>
            ))}
            <label className="flex items-center gap-1 rounded-xl bg-slate-50 px-2 py-1 text-[11px] font-bold text-slate-600">
              طول ≥
              <input
                aria-label="أدنى طول"
                value={minLen}
                onChange={(e) => setMinLen(e.target.value)}
                inputMode="numeric"
                placeholder="0"
                className="w-14 bg-transparent outline-none"
              />
              م
            </label>
            <label className="flex items-center gap-1 rounded-xl bg-slate-50 px-2 py-1 text-[11px] font-bold text-slate-600">
              <input type="checkbox" checked={noWidth} onChange={(e) => setNoWidth(e.target.checked)} />
              بلا عرض
            </label>
          </>
        }
      />

      {showColumns && (
        <ExportColumnsPanel
          kind="places"
          selection={selection}
          onChange={setOverride}
          sampleRows={exportRows}
          ctx={ctx}
        />
      )}

      {loading ? (
        <div className="h-40 animate-pulse rounded-2xl bg-slate-100" />
      ) : (
        <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-white">
          <table className="w-full text-right text-xs">
            <thead className="bg-slate-50 text-[11px] font-black text-slate-600">
              <tr>
                <th className="px-3 py-2">النوع</th>
                <th className="cursor-pointer px-3 py-2" onClick={() => sortBy('code')}>
                  الكود {sortKey === 'code' ? (asc ? '▲' : '▼') : ''}
                </th>
                <th className="cursor-pointer px-3 py-2" onClick={() => sortBy('name')}>
                  الاسم {sortKey === 'name' ? (asc ? '▲' : '▼') : ''}
                </th>
                <th className="px-3 py-2">التصنيف</th>
                <th className="cursor-pointer px-3 py-2" onClick={() => sortBy('length_m')}>
                  الطول {sortKey === 'length_m' ? (asc ? '▲' : '▼') : ''}
                </th>
                <th className="cursor-pointer px-3 py-2" onClick={() => sortBy('width_m')}>
                  العرض {sortKey === 'width_m' ? (asc ? '▲' : '▼') : ''}
                </th>
                <th className="px-3 py-2">المحلة</th>
                <th className="px-3 py-2">الحالة</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {rows.slice(0, 400).map((r) => (
                <tr
                  key={`${r.kind}-${r.id}`}
                  data-testid={`map-row-${r.kind}-${r.code}`}
                  role="button"
                  tabIndex={0}
                  aria-label={`عرض ${r.code} على الخريطة`}
                  title="اضغط لعرض موضعه على الخريطة"
                  onClick={() => openOnMap(r)}
                  onKeyDown={(e) => {
                    if (e.key !== 'Enter' && e.key !== ' ') return
                    e.preventDefault()
                    openOnMap(r)
                  }}
                  className="cursor-pointer transition hover:bg-cyan-50/70 focus:bg-cyan-50 focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-cyan-500"
                >
                  <td className="px-3 py-1.5 font-bold text-slate-500">
                    {r.kind === 'street' ? 'شارع' : 'زقاق'}
                  </td>
                  <td className="px-3 py-1.5 font-black text-slate-900">{r.code}</td>
                  <td className="px-3 py-1.5 text-slate-700">{r.name ?? '—'}</td>
                  <td className="px-3 py-1.5 text-slate-600">{r.cls}</td>
                  <td className="px-3 py-1.5 tabular-nums text-slate-700">
                    {Math.round(r.length_m)} م
                  </td>
                  <td className="px-3 py-1.5 tabular-nums">
                    {r.width_m === null ? (
                      <span className="rounded bg-amber-100 px-1.5 py-0.5 text-[10px] font-black text-amber-800">
                        غير مقيس
                      </span>
                    ) : (
                      `${r.width_m} م`
                    )}
                  </td>
                  <td className="px-3 py-1.5 text-slate-600">{r.mahalla}</td>
                  <td className="px-3 py-1.5 text-slate-500">{r.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {rows.length > 400 && (
            <p className="border-t bg-slate-50 px-3 py-2 text-center text-[11px] font-bold text-slate-500">
              يُعرض ٤٠٠ من {rows.length} — صدّر CSV للكل
            </p>
          )}
          {!rows.length && (
            <p className="px-3 py-8 text-center text-xs font-bold text-slate-400">
              لا صفوف تطابق الفلاتر
            </p>
          )}
        </div>
      )}

      <p className="text-center text-[10px] font-bold text-slate-400">
        المحلات: {mahallas.length} · 「غير محدّدة」{' '}
        {mahallas.find((m) => m.code === 'MHL-0000') ? 'موجودة' : 'غير موجودة'}
      </p>
    </div>
  )
}
